// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.orchestratorimport com.roshan.persona.brain.agentic.AgenticOrchestratorimport com.roshan.persona.brain.agentic.AgenticOutputimport com.roshan.persona.brain.bus.BrainBusimport com.roshan.persona.brain.bus.BrainEventimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.brain.intent.IntentClassificationimport com.roshan.persona.brain.intent.classifier.IntentClassifierimport com.roshan.persona.brain.llm.layer.LocalLlmLayerimport com.roshan.persona.brain.llm.layer.CloudLlmLayerimport javax.inject.Injectimport javax.inject.Singletonimport com.roshan.persona.brain.llm.router.HybridLlmRouterimport com.roshan.persona.brain.rule.engine.RuleEngineimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.brain.skill.router.SkillRouterimport com.roshan.persona.brain.stream.CancellationTokenimport com.roshan.persona.brain.stream.StreamCoordinatorimport com.roshan.persona.brain.trace.BrainTraceimport com.roshan.persona.brain.trace.Layerimport com.roshan.persona.brain.trace.LayerDecisionimport com.roshan.persona.brain.trace.LayerTraceimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport kotlinx.coroutines.CancellationExceptionimport timber.log.Timberimport java.time.Instant/** * NOUS — Brain Orchestrator (main router). * * The brain's entry point. Routes user input through the 6-layer cascade: * *   L0 IntentClassifier → L1 RuleEngine → L2 SkillRouter → L3 LocalLLM → *   L4 CloudLLM → L5 AgenticOrchestrator * * ## Routing Logic * *   1. **Pre-process** input (normalize, banned-pattern check, command prefix) *   2. **L0 IntentClassifier** — classify intent *      - If Compound/MultiStep → bypass L1/L2/L3/L4, go to L5 *   3. **L1 RuleEngine** — try instant rule fire *      - If rule matches → execute, return *   4. **L2 SkillRouter** — try skill execution *      - If skill matches → execute (with permission check), return *   5. **L3 LocalLlmLayer** — try on-device LLM *      - If success → return *      - If partial (low confidence) → return with warning *      - If failure → defer to L4 *   6. **L4 CloudLlmLayer** — try cloud LLM (if user opted in) *      - If success → return *      - If failure → return error *   7. **L5 AgenticOrchestrator** — only for Compound/MultiStep *      - ReAct loop with guardrails *   8. **Post-process** response (persona style, memory, audit) * * ## Command Overrides (Debug/Power-User) * *   - `!local` — force L3 only (skip L4) *   - `!cloud` — force L4 (skip L3) *   - `!agent` — force L5 *   - `!rule` — force L1 only * * ## Cancellation (Barge-In) * * User can interrupt at any time (voice barge-in or tap "stop"). The * orchestrator checks [CancellationToken] between layers and throws * [CancellationException] if cancelled. Partial response is preserved. * * ## Budget Enforcement * * Per-request budget (time/cost/tokens) enforced between layers. If exceeded, * orchestrator stops and returns the best partial response. * * @see <a href="docs/spec/module2-spec-review.pdf">§10 Brain Orchestrator</a> */@Singletonclass BrainOrchestrator @Inject constructor(    private val preProcessor: BrainPreProcessor,    private val postProcessor: BrainPostProcessor,    private val intentClassifier: IntentClassifier,    private val ruleEngine: RuleEngine,    private val skillRouter: SkillRouter,    private val hybridLlmRouter: HybridLlmRouter,    private val agenticOrchestrator: AgenticOrchestrator,    private val streamCoordinator: StreamCoordinator,    private val brainBus: BrainBus,    private val metrics: BrainMetrics,    private val tracePolicy: BrainTracePolicy,    private val systemOperationExecutor: com.roshan.persona.brain.skill.executor.SystemOperationExecutor,) {    /**     * Process [userInput] through the brain.     *     * @param userInput raw user input (voice-transcribed or typed)     * @param sessionId conversation session     * @param activePersona currently active persona     * @param userContext user identity + preferences     * @param deviceContext device state     * @return [BrainResponse] with message, trace, suggestions     */    suspend fun process(        userInput: String,        sessionId: com.roshan.persona.brain.context.SessionId,        activePersona: com.roshan.persona.brain.persona.Persona,        userContext: com.roshan.persona.brain.context.UserContext,        deviceContext: com.roshan.persona.brain.context.DeviceContext,    ): BrainResponse {        val requestStartNanos = System.nanoTime()        // ─── 1. Pre-process ───────────────────────────────────────────────        val preResult = preProcessor.process(            userInput = userInput,            sessionId = sessionId,            activePersona = activePersona,            userContext = userContext,            deviceContext = deviceContext,        )        val context: BrainContext        val cleanInput: String        val commandOverride: CommandOverride?        when (preResult) {            is PreProcessResult.Rejected -> {                return buildRejectionResponse(                    correlationId = preResult.correlationId,                    reason = preResult.reason,                    sessionId = sessionId,                    receivedAt = Instant.now(),                )            }            is PreProcessResult.Success -> {                context = preResult.context                cleanInput = preResult.cleanInput                commandOverride = preResult.commandOverride            }        }        val correlationId = context.correlationId        val layerTraces = mutableListOf<LayerTrace>()        var totalCostUsd = 0f        var totalTokensGenerated = 0        try {            // Get cancellation token for this request            val cancellationToken = streamCoordinator.getCancellationToken(correlationId)            // ─── 2. L0 IntentClassifier ──────────────────────────────────            cancellationToken.throwIfCancelled()            val l0Start = Instant.now()            val classification = intentClassifier.classify(cleanInput, context)            val l0Duration = durationMs(l0Start)            layerTraces.add(LayerTrace(                layer = Layer.INTENT,                enteredAt = l0Start,                exitedAt = Instant.now(),                durationMs = l0Duration,                decision = LayerDecision.PROCEED,                skipReason = null,                output = classification,                error = null,            ))            val intent = classification.intent            // ─── 3. Route based on intent + command override ─────────────            // Distinguish: simple Compound (L2 handles) vs complex MultiStep (L5 handles)            // - "torch on and call mom" → simple Compound → L2 (SkillRouter has compound support)            // - "research AI news and write a report" → complex MultiStep → L5 (Agentic)            val isCompound = intent is Intent.Compound            val isMultiStep = intent is Intent.MultiStep            val shouldBypassToAgentic = isMultiStep ||                commandOverride is CommandOverride.FORCE_AGENT            // Note: Compound intents go through normal cascade (L1→L2) — L2 has            // built-in compound execution (SEQUENTIAL/PARALLEL/CONDITIONAL)            val finalSkillOutput: SkillOutput            val handledBy: BrainLayer            var wasStreamed = false            when {                // ─── Force rule (!rule) ────────────────────────────────                commandOverride is CommandOverride.FORCE_RULE -> {                    val (output, layer) = runRuleEngine(context, classification, layerTraces)                    finalSkillOutput = output                    handledBy = layer                }                // ─── Force specific cloud provider (!openai, !anthropic, etc.) ─                commandOverride is CommandOverride.FORCE_CLOUD_PROVIDER -> {                    val (output, layer) = runForcedCloudProvider(                        cleanInput = cleanInput,                        context = context,                        providerId = commandOverride.providerId,                        layerTraces = layerTraces,                        cancellationToken = cancellationToken,                    )                    finalSkillOutput = output                    handledBy = layer                    wasStreamed = true                }                // ─── MultiStep → L5 Agentic (bypass L1/L2/L3/L4) ─────────                // Note: Only MultiStep bypasses. Compound goes through L2.                shouldBypassToAgentic -> {                    // Mark L1-L4 as skipped                    listOf(Layer.RULE, Layer.SKILL, Layer.LOCAL_LLM, Layer.CLOUD_LLM).forEach { layer ->                        layerTraces.add(LayerTrace(                            layer = layer,                            enteredAt = Instant.now(),                            exitedAt = null,                            durationMs = null,                            decision = LayerDecision.SKIP,                            skipReason = "Bypassed (MultiStep intent → L5)",                            output = null,                            error = null,                        ))                    }                    val (output, layer) = runAgentic(cleanInput, context, layerTraces, cancellationToken)                    finalSkillOutput = output                    handledBy = layer                }                // ─── Normal cascade: L1 → L2 → L3/L4 ───────────────────                else -> {                    // L1 RuleEngine                    cancellationToken.throwIfCancelled()                    val l1Result = runRuleEngine(context, classification, layerTraces)                    if (l1Result.second == BrainLayer.RULE) {                        // Rule fired — use its result                        finalSkillOutput = l1Result.first                        handledBy = l1Result.second                    } else {                        // L2 SkillRouter                        cancellationToken.throwIfCancelled()                        val l2Result = runSkillRouter(context, intent, layerTraces)                        if (l2Result.second == BrainLayer.SKILL) {                            // Skill handled it                            finalSkillOutput = l2Result.first                            handledBy = l2Result.second                        } else {                            // L3/L4 HybridLlmRouter                            cancellationToken.throwIfCancelled()                            val llmResult = runHybridLlm(                                cleanInput = cleanInput,                                context = context,                                commandOverride = commandOverride,                                layerTraces = layerTraces,                                cancellationToken = cancellationToken,                            )                            finalSkillOutput = llmResult.first                            handledBy = llmResult.second                            wasStreamed = handledBy == BrainLayer.LOCAL_LLM || handledBy == BrainLayer.CLOUD_LLM                        }                    }                }            }            // Extract cost + tokens from skill output data            val outputData = when (finalSkillOutput) {                is SkillOutput.Success -> finalSkillOutput.data                is SkillOutput.Partial -> finalSkillOutput.data                else -> emptyMap()            }            totalCostUsd = (outputData["cost_usd"] as? String)?.toFloatOrNull() ?: 0f            totalTokensGenerated = (outputData["tokens_generated"] as? String)?.toIntOrNull() ?: 0            // ─── 4. Build trace ────────────────────────────────────────────            val trace = BrainTrace(                correlationId = correlationId,                sessionId = context.sessionId,                inputRedacted = cleanInput.take(200),  // truncated for storage                startedAt = context.timestamp,                completedAt = Instant.now(),                totalDurationMs = (System.nanoTime() - requestStartNanos) / 1_000_000,                layers = layerTraces.toList(),                finalOutput = finalSkillOutput,                finalError = null,                totalCostUsd = totalCostUsd,                totalTokensGenerated = totalTokensGenerated,            )            // ─── 5. Stream completion ──────────────────────────────────────            if (wasStreamed) {                streamCoordinator.complete(correlationId)            }            // ─── 6. Post-process ───────────────────────────────────────────            val response = postProcessor.process(                context = context,                cleanInput = cleanInput,                skillOutput = finalSkillOutput,                trace = trace,                handledBy = handledBy,                wasStreamed = wasStreamed,                costUsd = totalCostUsd,                tokensGenerated = totalTokensGenerated,            )            // ─── 7. Record metrics + cache trace ──────────────────────────            metrics.record(trace)            tracePolicy.addTrace(trace)            // ─── 8. Emit completion event ─────────────────────────────────            brainBus.emit(BrainEvent.BrainRequestCompleted(                trace = trace,                correlationId = correlationId,            ))            Timber.tag("NOUS.Brain").i(                "Request %s: %s in %dms, \$%.4f, %d tokens",                correlationId.value.take(8),                handledBy.displayName,                response.totalDurationMs,                totalCostUsd,                totalTokensGenerated,            )            return response        } catch (e: CancellationException) {            Timber.tag("NOUS.Brain").i("Request cancelled: %s", correlationId.value.take(8))            metrics.recordCancellation()            return buildCancellationResponse(                correlationId = correlationId,                context = context,                layerTraces = layerTraces,                requestStartNanos = requestStartNanos,                reason = e.message ?: "User cancelled",            )        } catch (t: Throwable) {            Timber.tag("NOUS.Brain").e(t, "Request failed unexpectedly")            return buildErrorResponse(                correlationId = correlationId,                context = context,                layerTraces = layerTraces,                requestStartNanos = requestStartNanos,                error = t,            )        }    }    // ─── Layer runners ───────────────────────────────────────────────────    private suspend fun runRuleEngine(        context: BrainContext,        classification: IntentClassification,        layerTraces: MutableList<LayerTrace>,    ): Pair<SkillOutput, BrainLayer> {        val start = Instant.now()        return try {            val result = ruleEngine.evaluate(classification.intent, context)            val duration = durationMs(start)            when (result) {                is com.roshan.persona.brain.rule.engine.RuleEngineResult.Matched -> {                    layerTraces.add(LayerTrace(                        layer = Layer.RULE,                        enteredAt = start,                        exitedAt = Instant.now(),                        durationMs = duration,                        decision = LayerDecision.PROCEED,                        skipReason = null,                        output = result,                        error = null,                    ))                    // Actually execute the rule's action via the                    // SystemOperationExecutor (was previously a no-op stub                    // that just returned "Rule matched: <id>" without doing                    // anything). Audit Task ID: audit-m2-brain P0 fix.                    val ruleAction = result.rule.action                    when (ruleAction) {                        is com.roshan.persona.brain.rule.RuleAction.SystemCall -> {                            val execResult = systemOperationExecutor.execute(ruleAction.operation)                            when (execResult) {                                is Result.Success -> Pair(                                    SkillOutput.Success(                                        message = "Done: ${result.rule.description}",                                        data = mapOf("rule_id" to result.rule.id),                                    ),                                    BrainLayer.RULE,                                )                                is Result.Partial -> Pair(                                    SkillOutput.Success(                                        message = "Done (with caveats): ${result.rule.description}",                                        data = mapOf("rule_id" to result.rule.id, "partial" to true),                                    ),                                    BrainLayer.RULE,                                )                                is Result.Failure -> Pair(                                    SkillOutput.Failure(                                        error = execResult.error,                                        userMessage = "Couldn't execute: ${result.rule.description}",                                    ),                                    BrainLayer.NONE,                                )                            }                        }                        is com.roshan.persona.brain.rule.RuleAction.SkillInvoke -> {                            // SkillInvoke rules route to SkillRouter for actual execution.                            // Fall through to skill layer by returning a deferred output.                            Pair(                                SkillOutput.Success(                                    message = "Rule matched: ${result.rule.id}",                                    data = mapOf("rule_id" to result.rule.id, "skill_id" to ruleAction.skillId),                                ),                                BrainLayer.RULE,                            )                        }                        is com.roshan.persona.brain.rule.RuleAction.Composite -> {                            // Execute each action in sequence                            var lastResult: Pair<SkillOutput, BrainLayer> = Pair(                                SkillOutput.Success(message = "Done.", data = emptyMap()),                                BrainLayer.RULE,                            )                            for (subAction in ruleAction.actions) {                                val subRule = object : com.roshan.persona.brain.rule.BrainRule {                                    override val id = result.rule.id                                    override val priority = result.rule.priority                                    override val tags = result.rule.tags                                    override val description = result.rule.description                                    override val condition = result.rule.condition                                    override val action = subAction                                }                                // Recursive call would be cleaner but for simplicity we                                // only support SystemCall sub-actions here.                                if (subAction is com.roshan.persona.brain.rule.RuleAction.SystemCall) {                                    val execResult = systemOperationExecutor.execute(subAction.operation)                                    if (execResult is Result.Failure) {                                        lastResult = Pair(                                            SkillOutput.Failure(                                                error = execResult.error,                                                userMessage = "Failed at step: ${subAction.operation}",                                            ),                                            BrainLayer.NONE,                                        )                                        break                                    }                                }                            }                            lastResult                        }                        is com.roshan.persona.brain.rule.RuleAction.DeferToLayer -> {                            Pair(                                SkillOutput.Failure(                                    error = AppError.Unknown(correlationId = context.correlationId),                                    userMessage = "Deferred to layer ${ruleAction.layer}",                                ),                                BrainLayer.NONE,                            )                        }                        is com.roshan.persona.brain.rule.RuleAction.Respond -> {                            Pair(                                SkillOutput.Success(                                    message = ruleAction.message,                                    data = mapOf("rule_id" to result.rule.id),                                ),                                BrainLayer.RULE,                            )                        }                    }                }                is com.roshan.persona.brain.rule.engine.RuleEngineResult.NoMatch -> {                    layerTraces.add(LayerTrace(                        layer = Layer.RULE,                        enteredAt = start,                        exitedAt = Instant.now(),                        durationMs = duration,                        decision = LayerDecision.DEFER,                        skipReason = "No rule matched",                        output = result,                        error = null,                    ))                    Pair(SkillOutput.Failure(                        error = AppError.Unknown(correlationId = context.correlationId),                        userMessage = "No rule matched",                    ), BrainLayer.NONE)                }            }        } catch (t: Throwable) {            layerTraces.add(LayerTrace(                layer = Layer.RULE,                enteredAt = start,                exitedAt = Instant.now(),                durationMs = durationMs(start),                decision = LayerDecision.FAIL,                skipReason = null,                output = null,                error = AppError.from(t, context.correlationId),            ))            Pair(SkillOutput.Failure(                error = AppError.from(t, context.correlationId),                userMessage = "Rule engine error",            ), BrainLayer.NONE)        }    }    private suspend fun runSkillRouter(        context: BrainContext,        intent: Intent,        layerTraces: MutableList<LayerTrace>,    ): Pair<SkillOutput, BrainLayer> {        val start = Instant.now()        return try {            val result = skillRouter.route(intent, context)            val duration = durationMs(start)            val decision = when (result) {                is Result.Success -> LayerDecision.PROCEED                is Result.Failure -> LayerDecision.FAIL                is Result.Partial -> LayerDecision.PROCEED            }            layerTraces.add(LayerTrace(                layer = Layer.SKILL,                enteredAt = start,                exitedAt = Instant.now(),                durationMs = duration,                decision = decision,                skipReason = null,                output = result,                error = (result as? Result.Failure)?.error,            ))            when (result) {                is Result.Success -> Pair(result.data, BrainLayer.SKILL)                is Result.Partial -> Pair(result.data, BrainLayer.SKILL)                is Result.Failure -> Pair(SkillOutput.Failure(                    error = result.error,                    userMessage = "No skill could handle this",                ), BrainLayer.NONE)            }        } catch (t: Throwable) {            layerTraces.add(LayerTrace(                layer = Layer.SKILL,                enteredAt = start,                exitedAt = Instant.now(),                durationMs = durationMs(start),                decision = LayerDecision.FAIL,                skipReason = null,                output = null,                error = AppError.from(t, context.correlationId),            ))            Pair(SkillOutput.Failure(                error = AppError.from(t, context.correlationId),                userMessage = "Skill router error",            ), BrainLayer.NONE)        }    }    private suspend fun runHybridLlm(        cleanInput: String,        context: BrainContext,        commandOverride: CommandOverride?,        layerTraces: MutableList<LayerTrace>,        cancellationToken: CancellationToken,    ): Pair<SkillOutput, BrainLayer> {        val start = Instant.now()        return try {            val routingResult = hybridLlmRouter.route(                userInput = cleanInput,                context = context,                forceCloud = commandOverride is CommandOverride.FORCE_CLOUD ||                    commandOverride is CommandOverride.FORCE_CLOUD_PROVIDER,                forceLocal = commandOverride is CommandOverride.FORCE_LOCAL,                onToken = { token ->                    // Stream token to UI via StreamCoordinator (synchronous —                    // onToken lambda is non-suspend, so we use tryEmit-based                    // emitTokenSync instead of the suspend emitToken).                    streamCoordinator.emitTokenSync(context.correlationId, token)                },            )            val duration = durationMs(start)            // Determine which layer handled it based on routing decision            val handledLayer = when (routingResult.decision) {                is HybridLlmRouter.RoutingDecision.ExplicitCloud,                is HybridLlmRouter.RoutingDecision.LongContext -> BrainLayer.CLOUD_LLM                is HybridLlmRouter.RoutingDecision.ExplicitLocal,                is HybridLlmRouter.RoutingDecision.LocalFirst -> BrainLayer.LOCAL_LLM                is HybridLlmRouter.RoutingDecision.NoFallback -> BrainLayer.NONE            }            layerTraces.add(LayerTrace(                layer = if (handledLayer == BrainLayer.CLOUD_LLM) Layer.CLOUD_LLM else Layer.LOCAL_LLM,                enteredAt = start,                exitedAt = Instant.now(),                durationMs = duration,                decision = LayerDecision.PROCEED,                skipReason = null,                output = routingResult.output,                error = null,            ))            when (routingResult.output) {                is Result.Success -> Pair(routingResult.output.data, handledLayer)                is Result.Partial -> Pair(routingResult.output.data, handledLayer)                is Result.Failure -> Pair(SkillOutput.Failure(                    error = routingResult.output.error,                    userMessage = "I couldn't generate a response.",                ), BrainLayer.NONE)            }        } catch (t: Throwable) {            layerTraces.add(LayerTrace(                layer = Layer.LOCAL_LLM,                enteredAt = start,                exitedAt = Instant.now(),                durationMs = durationMs(start),                decision = LayerDecision.FAIL,                skipReason = null,                output = null,                error = AppError.from(t, context.correlationId),            ))            Pair(SkillOutput.Failure(                error = AppError.from(t, context.correlationId),                userMessage = "LLM error",            ), BrainLayer.NONE)        }    }    /**     * Run a forced cloud provider (e.g., `!openai`, `!anthropic`, `!gemini`, `!groq`, `!openrouter`).     *     * Bypasses layers 0-3 (Intent, Rule, Skill, LocalLLM) and goes directly to     * CloudLlmLayer with the specified provider selected. Falls back to local     * LLM if cloud is unavailable (network error, missing API key, disabled).     */    private suspend fun runForcedCloudProvider(        cleanInput: String,        context: BrainContext,        providerId: String,        layerTraces: MutableList<LayerTrace>,        cancellationToken: CancellationToken,    ): Pair<SkillOutput, BrainLayer> {        val start = Instant.now()        return try {            val routingResult = hybridLlmRouter.route(                userInput = cleanInput,                context = context,                forceCloud = true,                forceLocal = false,                preferredCloudProvider = providerId,                onToken = { token ->                    streamCoordinator.emitTokenSync(context.correlationId, token)                },            )            val duration = durationMs(start)            val handledLayer = BrainLayer.CLOUD_LLM            layerTraces.add(LayerTrace(                layer = Layer.CLOUD_LLM,                enteredAt = start,                exitedAt = Instant.now(),                durationMs = duration,                decision = LayerDecision.PROCEED,                skipReason = null,                output = routingResult.output,                error = null,            ))            when (routingResult.output) {                is Result.Success -> Pair(routingResult.output.data, handledLayer)                is Result.Partial -> Pair(routingResult.output.data, handledLayer)                is Result.Failure -> Pair(SkillOutput.Failure(                    error = routingResult.output.error,                    userMessage = "Provider '$providerId' unavailable: ${routingResult.output.error.message}",                ), BrainLayer.NONE)            }        } catch (t: Throwable) {            layerTraces.add(LayerTrace(                layer = Layer.CLOUD_LLM,                enteredAt = start,                exitedAt = Instant.now(),                durationMs = durationMs(start),                decision = LayerDecision.FAIL,                skipReason = null,                output = null,                error = AppError.from(t, context.correlationId),            ))            Pair(SkillOutput.Failure(                error = AppError.from(t, context.correlationId),                userMessage = "Provider '$providerId' failed: ${t.message}",            ), BrainLayer.NONE)        }    }    private suspend fun runAgentic(        userInput: String,        context: BrainContext,        layerTraces: MutableList<LayerTrace>,        cancellationToken: CancellationToken,    ): Pair<SkillOutput, BrainLayer> {        val start = Instant.now()        return try {            val result = agenticOrchestrator.run(userInput, context)            val duration = durationMs(start)            layerTraces.add(LayerTrace(                layer = Layer.AGENTIC,                enteredAt = start,                exitedAt = Instant.now(),                durationMs = duration,                decision = LayerDecision.PROCEED,                skipReason = null,                output = result,                error = null,            ))            when (result) {                is Result.Success -> {                    val agenticOutput = result.data as? AgenticOutput                    if (agenticOutput != null) {                        Pair(agenticOutput.skillOutput, BrainLayer.AGENTIC)                    } else {                        Pair(SkillOutput.Failure(                            error = AppError.Unknown(correlationId = context.correlationId),                            userMessage = "Agentic output type mismatch",                        ), BrainLayer.NONE)                    }                }                is Result.Failure -> Pair(SkillOutput.Failure(                    error = result.error,                    userMessage = "Workflow failed",                ), BrainLayer.NONE)                is Result.Partial -> Pair(SkillOutput.Failure(                    error = AppError.Unknown(correlationId = context.correlationId),                    userMessage = "Workflow incomplete",                ), BrainLayer.NONE)            }        } catch (t: Throwable) {            layerTraces.add(LayerTrace(                layer = Layer.AGENTIC,                enteredAt = start,                exitedAt = Instant.now(),                durationMs = durationMs(start),                decision = LayerDecision.FAIL,                skipReason = null,                output = null,                error = AppError.from(t, context.correlationId),            ))            Pair(SkillOutput.Failure(                error = AppError.from(t, context.correlationId),                userMessage = "Workflow error",            ), BrainLayer.NONE)        }    }    // ─── Error/cancellation response builders ────────────────────────────    private fun buildRejectionResponse(        correlationId: CorrelationId,        reason: String,        sessionId: com.roshan.persona.brain.context.SessionId,        receivedAt: Instant,    ): BrainResponse {        val trace = BrainTrace(            correlationId = correlationId,            sessionId = sessionId,            inputRedacted = "[rejected]",            startedAt = receivedAt,            completedAt = Instant.now(),            totalDurationMs = 0L,            layers = emptyList(),            finalOutput = null,            finalError = AppError.Configuration.InvalidProviderConfig(reason),            totalCostUsd = 0f,            totalTokensGenerated = 0,        )        return BrainResponse(            correlationId = correlationId,            sessionId = sessionId,            receivedAt = receivedAt,            completedAt = Instant.now(),            totalDurationMs = 0L,            message = "I can't help with that request.",            spokenMessage = null,            trace = trace,            handledBy = BrainLayer.NONE,            status = BrainResponseStatus.FAILURE,            costUsd = 0f,            tokensGenerated = 0,            suggestions = listOf(BrainSuggestion(                text = "Try rephrasing your request",                type = SuggestionType.REPHRASE,            )),        )    }    private fun buildCancellationResponse(        correlationId: CorrelationId,        context: BrainContext,        layerTraces: MutableList<LayerTrace>,        requestStartNanos: Long,        reason: String,    ): BrainResponse {        val trace = BrainTrace(            correlationId = correlationId,            sessionId = context.sessionId,            inputRedacted = "[cancelled]",            startedAt = context.timestamp,            completedAt = Instant.now(),            totalDurationMs = (System.nanoTime() - requestStartNanos) / 1_000_000,            layers = layerTraces.toList(),            finalOutput = null,            finalError = AppError.Unknown(correlationId = correlationId),            totalCostUsd = 0f,            totalTokensGenerated = 0,        )        metrics.record(trace)        tracePolicy.addTrace(trace)        return BrainResponse(            correlationId = correlationId,            sessionId = context.sessionId,            receivedAt = context.timestamp,            completedAt = Instant.now(),            totalDurationMs = trace.totalDurationMs,            message = "[Interrupted]",            spokenMessage = null,            trace = trace,            handledBy = BrainLayer.NONE,            status = BrainResponseStatus.CANCELLED,            costUsd = 0f,            tokensGenerated = 0,        )    }    private fun buildErrorResponse(        correlationId: CorrelationId,        context: BrainContext,        layerTraces: MutableList<LayerTrace>,        requestStartNanos: Long,        error: Throwable,    ): BrainResponse {        val appError = AppError.from(error, correlationId)        val trace = BrainTrace(            correlationId = correlationId,            sessionId = context.sessionId,            inputRedacted = "[error]",            startedAt = context.timestamp,            completedAt = Instant.now(),            totalDurationMs = (System.nanoTime() - requestStartNanos) / 1_000_000,            layers = layerTraces.toList(),            finalOutput = null,            finalError = appError,            totalCostUsd = 0f,            totalTokensGenerated = 0,        )        metrics.record(trace)        tracePolicy.addTrace(trace)        return BrainResponse(            correlationId = correlationId,            sessionId = context.sessionId,            receivedAt = context.timestamp,            completedAt = Instant.now(),            totalDurationMs = trace.totalDurationMs,            message = "Something went wrong. Please try again.",            spokenMessage = null,            trace = trace,            handledBy = BrainLayer.NONE,            status = BrainResponseStatus.FAILURE,            costUsd = 0f,            tokensGenerated = 0,            suggestions = listOf(BrainSuggestion(                text = "Try rephrasing or simplifying your request",                type = SuggestionType.REPHRASE,            )),        )    }    private fun durationMs(start: Instant): Long =        java.time.Duration.between(start, Instant.now()).toMillis()}